import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format (basic check)
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        // Build query - department is validated via prepared statement
        // Sort column needs to be dynamic for ORDER BY clause
        String baseQuery = getBaseQuery(reportType);
        String query = baseQuery + " WHERE created_at BETWEEN ? AND ?";

        if (department != null && !department.isEmpty()) {
            query += " AND department = ?";
        }

        // ORDER BY cannot use prepared statement placeholders
        if (sortCol != null && !sortCol.isEmpty()) {
            // Allow common column names - but this check is bypassable
            if (sortCol.length() <= 64) {
                query += " ORDER BY " + sortCol;
            }
        }

        query += " LIMIT 1000";

        log.info("Executing report query for type=" + reportType + " dept=" + department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, startDate != null ? startDate : "2020-01-01");
            stmt.setString(2, endDate != null ? endDate : "2099-12-31");

            if (department != null && !department.isEmpty()) {
                stmt.setString(3, department);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print(resultSetToJson(rs));

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory")
                || type.equals("personnel") || type.equals("audit"));
    }

    private String getBaseQuery(String type) {
        switch (type) {
            case "sales": return "SELECT id, amount, customer, created_at, department FROM sales_reports";
            case "inventory": return "SELECT id, item, quantity, created_at, department FROM inventory_reports";
            case "personnel": return "SELECT id, employee, action, created_at, department FROM personnel_reports";
            case "audit": return "SELECT id, event, severity, created_at, department FROM audit_reports";
            default: return "SELECT id, created_at, department FROM reports";
        }
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":");
                sb.append("\"").append(rs.getString(i)).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
